import com.application.requiemproject.domain.repository.HelpRepository

class LocalHelpRepository : HelpRepository {
    override fun articles() = listOf(
        HelpArticle(1, "Как начать перевод?", "Начало", "Выберите исходный язык и язык перевода на главном экране. Нажмите «Начать перевод», разрешите наложение поверх приложений и подтвердите захват экрана. Затем откройте нужное приложение."),
        HelpArticle(2, "OCR или Accessibility?", "Перевод", "OCR распознаёт текст на изображении. Accessibility читает доступный текст элементов интерфейса; для него нужно включить службу Requiem в специальных возможностях Android. Текст для перевода отправляется сервису MyMemory."),
